import {
  DESPOTISM_PENALTY,
  TRADE_BONUS,
  governmentTileYield,
  governmentTileYieldTypes,
} from '@civ-clone/civ1-world/lib/governmentTileYield';
import {
  PendingEffectRegistry,
  instance as pendingEffectRegistryInstance,
} from '@civ-clone/core-pending-effect';
import {
  PlayerGovernmentRegistry,
  instance as playerGovernmentRegistryInstance,
} from '@civ-clone/core-government/PlayerGovernmentRegistry';
import {
  TileImprovementRegistry,
  instance as tileImprovementRegistryInstance,
} from '@civ-clone/core-tile-improvement/TileImprovementRegistry';
import City from '@civ-clone/core-city/City';
import CityYield from '@civ-clone/core-city/Rules/Yield';
import Criterion from '@civ-clone/core-rule/Criterion';
import Effect from '@civ-clone/core-rule/Effect';
import PlayerGovernment from '@civ-clone/core-government/PlayerGovernment';
import { Pollution } from '@civ-clone/civ1-world/TileImprovements';
import Priority from '@civ-clone/core-rule/Priority';
import TileImprovement from '@civ-clone/core-tile-improvement/TileImprovement';
import Yield from '@civ-clone/core-yield/Yield';
import celebrationYields, {
  AfterSteps,
} from '@civ-clone/base-city-celebration-yields/lib/celebrationYields';
import { leaderCelebration } from '../../lib/cityStatus';

// The providers of what the government and pollution did to a square, which a celebrating city works out again.
const governmentSteps = [DESPOTISM_PENALTY, TRADE_BONUS, Pollution.name];

export const getRules: (
  pendingEffects?: PendingEffectRegistry,
  playerGovernmentRegistry?: PlayerGovernmentRegistry,
  tileImprovementRegistry?: TileImprovementRegistry
) => CityYield[] = (
  pendingEffects: PendingEffectRegistry = pendingEffectRegistryInstance,
  playerGovernmentRegistry: PlayerGovernmentRegistry = playerGovernmentRegistryInstance,
  tileImprovementRegistry: TileImprovementRegistry = tileImprovementRegistryInstance
): CityYield[] => [
  // A celebrating city's squares escape the Anarchy and Despotism penalty, and under Monarchy and Communism get The
  //  Republic's trade bonus (civ-clone/web-renderer#401). v474.05 (`CITYMGT.C` `tile_yield`):
  //    if (yield_value_n > 2 && !(townbuf[selected_city].status & CITY_CELEBRATING)) {
  //      if (civ_gov[selected_owner] <= 1) yield_value_n--; ... }                                    (1981-1983)
  //    if ((townbuf[selected_city].status & CITY_CELEBRATING ? 2 : 4) <= civ_gov[selected_owner])
  //      yield_value_n++;                                                                (trade only, 1990-1991)
  //  It reads the flag, not whether the city is celebrating now, so a celebrating city in civil disorder, which keeps
  //  its flag, keeps these too, as the record here is kept (`turn-start`, civ-clone/web-renderer#1013). A square's own
  //  yields are worked out for a city that isn't celebrating, as they're kept per player, so this adds the difference:
  //  what the square yields before the government's steps, through them again as a celebrating city, then pollution.
  //  After the worked squares, and before trade routes and corruption, which count it.
  new CityYield(
    'civ1-city-happiness:city/yield/celebration',
    new Priority(1),
    new Criterion(
      (city: City): boolean => leaderCelebration(city, pendingEffects) !== null
    ),
    new Effect((city: City): Yield[] => {
      let government: PlayerGovernment;

      try {
        government = playerGovernmentRegistry.getByPlayer(city.player());
      } catch (e) {
        return [];
      }

      // Pollution halves what the steps leave, rounded up, as civ1-world's tile rules do.
      const afterSteps: AfterSteps = (tile) =>
        tileImprovementRegistry
          .getByTile(tile)
          .some(
            (improvement: TileImprovement): boolean =>
              improvement instanceof Pollution
          )
          ? (value: number): number => Math.ceil(value / 2)
          : (value: number): number => value;

      return celebrationYields(
        city,
        government,
        governmentTileYieldTypes,
        governmentSteps,
        governmentTileYield,
        afterSteps
      );
    })
  ),
];

export default getRules;
