// The engine events that change what the player is sent (#449), moved out of `DataTransferClient`: each listener queues
//  the patches for what the event changed, which are built and sent at the next flush. One of them flushes: every
//  `unit:moved`, anyone's, which is how the AI's moves reach the UI.
//
// What the player is told of these events is in `notifications/`, registered after these, so that what an event
//  changes is queued before the player is told of it.

import Advance from '@civ-clone/core-science/Advance';
import City from '@civ-clone/core-city/City';
import CityBuild from '@civ-clone/core-city-build/CityBuild';
import CityImprovement from '@civ-clone/core-city-improvement/CityImprovement';
import Civilization from '@civ-clone/core-civilization/Civilization';
import Engine from '@civ-clone/core-engine/Engine';
import GoodyHut from '@civ-clone/core-goody-hut/GoodyHut';
import JoinCity from '@civ-clone/library-unit/Actions/JoinCity';
import Player from '@civ-clone/core-player/Player';
import PlayerAction from '@civ-clone/core-player/PlayerAction';
import PlayerTile from '@civ-clone/core-player-world/PlayerTile';
import PlayerWorld from '@civ-clone/core-player-world/PlayerWorld';
import Tile from '@civ-clone/core-world/Tile';
import Unit from '@civ-clone/core-unit/Unit';
import UnitAction from '@civ-clone/core-unit/Action';
import Yield from '@civ-clone/core-yield/Yield';
import Automation from '../Automation';
import { CityNewsCollector } from '../cityNews';
import { ClientContext, Disposer, Registries } from '../ClientContext';
import { filterToReference, filterToReferenceAllExcept } from '../refs';
import { knownUnknownCity } from '../standIns';
import type UnknownCity from '../../UnknownObjects/City';
import { workerRules } from '../../workerRules';

export type PatchEventsContext = Pick<
  ClientContext,
  | 'view'
  // The patches queued for the player, and the flush that sends them.
  | 'patches'
  // What the player may see, which a rival's city, a build or research goes through when it changes.
  | 'dataFilter'
> &
  // What the player knows of a square, the city on one and the units on one; and a player's cities, and every city, for
  //  the cities a changed square or a rival's advance changes (M2c).
  Registries<{
    cities: 'getByTile' | 'getByPlayer' | 'entries';
    units: 'getByTile';
  }> & {
    // Whether this is our turn, automated, read as each event happens: automation is turned on and off mid-game.
    automation: Pick<Automation, 'automatedTurn'>;
    // What happened to each city during the engine call under way: a city captured from us, destroyed or abandoned.
    cityNews: Pick<CityNewsCollector, 'of'>;
  };

export const registerPatchEvents = (
  engine: Pick<Engine, 'on' | 'off'>,
  ctx: PatchEventsContext
): Disposer => {
  const listeners: [string, (...args: any[]) => void][] = [],
    on = (event: string, listener: (...args: any[]) => void): void => {
      engine.on(event, listener);

      listeners.push([event, listener]);
    };

  on('player:visibility-changed', (tile, player) => {
    if (!ctx.view.owns(player)) {
      return;
    }

    const playerTile = ctx.view.tile(tile);

    // A square newly seen in one of our cities' areas is one of its `tiles` from now on, where it was undiscovered
    //  (#411).
    if (!ctx.automation.automatedTurn()) {
      ctx.patches.citiesAround(tile);
    }

    // `PlayerWorld.register` adds the square before it says it is seen, so it is never missing here (#478).
    if (playerTile === null) {
      // Never reached today (`PlayerWorld.register` adds the tile before the rule fires); say so if it ever is,
      //  rather than dropping the square silently.
      console.warn(
        `visibility-changed: no PlayerTile yet for ${tile.x()},${tile.y()}`
      );

      return;
    }

    ctx.patches.seenTile(ctx.view.world(), playerTile);
  });

  ['unit:created', 'unit:defeated', 'unit:lost-at-sea'].forEach((event) => {
    on(event, (unit) => {
      const playerTile = ctx.view.tile(unit.tile());

      if (!playerTile) {
        return;
      }

      ctx.patches.tile(playerTile);

      if (!ctx.view.owns(unit.player())) {
        return;
      }

      // The unit, the player's list of units, and its home city, which supports it (#411). Each is built when the
      //  patch is sent, so a unit gone by then, a Settlers that founded a city, isn't put back (#138).
      ctx.patches.unit(unit);
      ctx.patches.city(unit.city());

      if (event === 'unit:created') {
        ctx.patches.playerKey('units');
      }
    });
  });

  // The winner of a battle in rounds (M2b) comes out of it damaged: its square goes again, with its hit points, and the
  //  unit itself if it's ours. Only a unit with damage: a game without it (Civ1) sends what it always did.
  on('unit:defeated', (loser: Unit, winner?: Unit) => {
    if (!winner || winner.destroyed() || winner.damage() === 0) {
      return;
    }

    const playerTile = ctx.view.tile(winner.tile());

    if (!playerTile) {
      return;
    }

    ctx.patches.tile(playerTile);

    if (ctx.view.owns(winner.player())) {
      ctx.patches.unit(winner);
    }
  });

  // A unit of ours promoted after a win (M2b, `unit:promoted`, which only rules that promote emit), damaged or not: it
  //  goes again as a veteran, with its square. In an AI's turn nothing else sends it until the next hand-over.
  on('unit:promoted', (unit: Unit) => {
    if (!ctx.view.owns(unit.player())) {
      return;
    }

    ctx.patches.tile(ctx.view.tile(unit.tile()));
    ctx.patches.unit(unit);
  });

  // A unit upgraded in place (M2c, `unit:upgraded`): its square goes again, which a rival's unit's stand-in, as its
  //  type is read from the unit, is drawn on as its new type, where the player knows the square; and one of ours goes
  //  again in full.
  on('unit:upgraded', (unit: Unit) => {
    const playerTile = ctx.view.tile(unit.tile());

    if (playerTile) {
      ctx.patches.tile(playerTile);
    }

    if (ctx.view.owns(unit.player())) {
      ctx.patches.unit(unit);
    }
  });

  ['unit:destroyed'].forEach((event) => {
    on(event, (unit: Unit) => {
      // A disbanded or destroyed unit leaves its square, whoever's it was (#138).
      ctx.patches.tile(unit.tile());

      // It goes once more, marked destroyed, and then drops out of the player's list of units, which no longer holds
      //  it or the home city it kept (#459). Its home city no longer supports it (#411).
      ctx.patches.unit(unit);
      ctx.patches.city(unit.city());

      if (ctx.view.owns(unit.player())) {
        ctx.patches.playerKey('units');
      }
    });
  });

  ['unit:moved'].forEach((event) => {
    on(event, (unit: Unit, action: UnitAction) => {
      const fromTile = ctx.view.tile(action.from()),
        toTile = ctx.view.tile(action.to());

      if (!fromTile && !toTile) {
        return;
      }

      ctx.patches.tile(fromTile);
      ctx.patches.tile(toTile);

      // A Settlers joining a city makes it grow, so the city goes out in full, as `city:grow` sends it. In the tile
      //  patch alone the city is a ref, and would keep the size the UI already has (#243).
      if (action instanceof JoinCity) {
        const city = ctx.cities.getByTile(action.to());

        if (city !== null) {
          ctx.patches.city(city);
        }
      }

      // The unit, and the city that supports it, which may be unhappy about where it is now (#411).
      if (ctx.view.owns(unit.player()) && !ctx.automation.automatedTurn()) {
        ctx.patches.unit(unit);
        ctx.patches.city(unit.city());
        ctx.patches.onTiles(action.from(), action.to());
      }

      ctx.patches.flush();
    });
  });

  [
    'tile-improvement:built',
    'tile-improvement:pillaged',
    'tile-improvement:removed',
  ].forEach((event) => {
    on(event, (tile: Tile) => {
      ctx.patches.tile(tile);

      // Under rules where a square yields its city something of its own (Civ2's `squareYields`, M2c), each of our
      //  cities with the square in its radius goes again too, with its figures. Not under Civ1's, whose payload and
      //  cost stay as they were.
      if (workerRules().citySquareYields !== true) {
        return;
      }

      ctx.cities
        .entries()
        .filter(
          (city: City) =>
            ctx.view.owns(city.player()) &&
            city.tile().distanceFrom(tile) <= 3 &&
            city.tiles().entries().includes(tile)
        )
        .forEach((city: City) => ctx.patches.city(city));
    });
  });

  on(
    'city:captured',
    (city: City, capturingPlayer: Player, originalPlayer: Player) => {
      // A city lost or won can take the capital our other cities' corruption is measured from, or bring or take a
      //  wonder that works in all of them, so they all go in full (#515): nothing else in this flush sends them in full
      //  (for a city lost, the whole player below sends them as refs), and the next turn's hand-over, which does, is
      //  too late for a city screen open until then. A size 1 city that its capture destroys is already the
      //  capturer's when `city:destroyed` is raised, so that loss is sent from here.
      if (
        [capturingPlayer, originalPlayer].some((player) =>
          ctx.view.owns(player)
        )
      ) {
        ctx.patches.cities();
      }

      // Our capture of it is told in `Client/notifications/city.ts`.
      if (ctx.view.owns(originalPlayer)) {
        // The city already belongs to the capturing player here, so resend ours: the city is gone from our list.
        ctx.patches.wholePlayer(
          filterToReferenceAllExcept(Player, PlayerAction, Civilization)
        );

        Object.assign(ctx.cityNews.of(city), {
          capturedBy: capturingPlayer,
          capturedFrom: originalPlayer,
        });
      }

      // A size 1 city that our capture destroyed was already ours when that was heard of (`capture()` hands it over
      //  before the rules that destroy it run), but it is no loss of ours (#501): the capture is told in
      //  `Client/notifications/city.ts`.
      if (ctx.view.owns(capturingPlayer) && !ctx.view.owns(originalPlayer)) {
        ctx.cityNews.of(city).ours = false;
      }
    }
  );

  // The map draws a city from its tile: its size, or an unhappy citizen in civil disorder (#193). Our own city is a
  //  ref in the tile patch, so it goes out in full along with it: a new or captured city the frontend has never had,
  //  or a size or disorder the map draws from it. Not a destroyed one.
  const cityChanged = (
    city: City,
    destroyed: boolean = false,
    listChanged: boolean = false
  ): void => {
    const playerTile = ctx.view.tile(city.tile());

    if (!playerTile) {
      return;
    }

    const unknownCity = knownUnknownCity(city);

    if (unknownCity) {
      ctx.patches.update(unknownCity.id(), () => {
        unknownCity.update(city);

        return unknownCity.toPlainObject(
          ctx.dataFilter(filterToReference(Tile, Unit, Player))
        );
      });
    }

    ctx.patches.tile(playerTile);

    if (!destroyed) {
      ctx.patches.city(city);
    }

    // A city founded, captured or destroyed is added to or gone from the player's list of cities (#411).
    if (listChanged && ctx.view.owns(city.player())) {
      ctx.patches.playerKey('cities');
    }
  };

  [
    'city:created',
    'city:captured',
    'city:grow',
    'city:shrink',
    // A rival's city in disorder shows on the map as your own does (#265). The engine raises
    //  `city:civil-disorder` before it records the disorder, which is why the city is only read when the patch is
    //  built.
    'city:civil-disorder',
    'city:order-restored',
  ].forEach((event) =>
    on(event, (city: City) =>
      cityChanged(
        city,
        false,
        ['city:created', 'city:captured'].includes(event)
      )
    )
  );

  // A size 1 city that its own Settlers are about to remove (#969). The engine says so before it announces the build
  //  and destroys the city, all in one engine call, so the build isn't told and the city's news says it once.
  on('city:abandoned', (city: City) => {
    ctx.cityNews.of(city).abandoned = true;
  });

  on('city:destroyed', (city: City, player: Player | null) => {
    cityChanged(city, true, true);

    // Our other cities, as for one captured from us (#515): it may have been the capital, or held a wonder.
    if (ctx.view.owns(city.player())) {
      ctx.patches.cities();
    }

    Object.assign(ctx.cityNews.of(city), {
      destroyed: true,
      destroyedBy: player ?? null,
    });
  });

  // Which city works a tile is part of the tile (`workedBy`), so it goes out whenever that changes (#138): a city
  //  founded, growing, shrinking or destroyed, a tile the player chose, workers reassigned, an enemy unit in the way.
  //  The city's yields change with it, so ours goes too (#411): a city founded next to it takes a square it worked.
  ['city:tile-worked', 'city:tile-released'].forEach((event) =>
    on(event, (city: City, tile: Tile) => {
      ctx.patches.tile(tile);

      if (!ctx.automation.automatedTurn()) {
        ctx.patches.city(city);
      }
    })
  );

  // A government's yields reach every city and many squares, so a change of government sends the cities and the
  //  squares whose yields it changed (#488): whatever changed it, a revolution, a new government chosen, or one that
  //  collapsed.
  on('player:government:changed', (player: Player) => {
    if (ctx.view.owns(player)) {
      ctx.patches.governmentChanged();
    }
  });

  // A nuclear detonation (#129). The engine announces it before anything changes, and patches are only built when
  //  they're sent, so every square in the 3×3 area and every city in it is queued here and read once the units are
  //  gone and the cities halved. The other players are told of it in `Client/notifications/unit.ts`.
  on('unit:nuclear-detonation', (_unit: Unit, tile: Tile) => {
    const area = [tile, ...tile.getNeighbours()],
      cities = area
        .map((areaTile) => ctx.cities.getByTile(areaTile))
        .filter((city): city is City => city !== null);

    area.forEach((areaTile) => ctx.patches.tile(areaTile));

    cities.forEach((city) => cityChanged(city));

    if (
      cities.some((city) => ctx.view.owns(city.player())) ||
      area.some((areaTile) =>
        ctx.units
          .getByTile(areaTile)
          .some((areaUnit) => ctx.view.owns(areaUnit.player()))
      )
    ) {
      ctx.patches.wholePlayer(
        filterToReferenceAllExcept(
          Player,
          PlayerAction,
          Unit,
          UnitAction,
          Yield,
          Civilization
        )
      );
    }
  });

  // A Nuclear Plant's meltdown (M2c): the city loses the plant, and the squares around it what the blast took, which
  //  each go as they're removed; the city goes again too.
  on('city:nuclear-meltdown', (city: City) => {
    [city.tile(), ...city.tile().getNeighbours()].forEach((tile) =>
      ctx.patches.tile(tile)
    );

    cityChanged(city);
  });

  // A warming changes the land with no unit acting (base-global-warming, M2e): each square we know goes again, and so
  //  do our cities, whose squares may yield less now.
  on('world:global-warming', (_warmings: number, changed: Tile[]) => {
    changed.forEach((tile: Tile) => ctx.patches.tile(tile));

    if (changed.length > 0) {
      ctx.patches.cities();
    }
  });

  // A civil war (base-civil-war, M2e) hands cities and units to the rebels as they are, with no capture and no move:
  //  each city goes again, with the squares around it where its units may stand, and a side that's ours goes in full.
  on('player:civil-war', (loser: Player, rebels: Player, cities: City[]) => {
    cities.forEach((city: City) => {
      cityChanged(city, false, true);
      city
        .tile()
        .getNeighbours()
        .forEach((tile: Tile) => ctx.patches.tile(tile));
    });

    if ([loser, rebels].some((player) => ctx.view.owns(player))) {
      ctx.patches.cities();
      ctx.patches.wholePlayer(
        filterToReferenceAllExcept(Player, PlayerAction, Civilization)
      );
    }
  });

  // Both cities' trade changes (#411). The player is told of it in `Client/notifications/unit.ts`.
  on(
    'unit:trade-route-established',
    (player: Player, home: City, city: City) => {
      if (!ctx.view.owns(player)) {
        return;
      }

      ctx.patches.city(home);
      ctx.patches.city(city);
    }
  );

  // A bribed or defecting unit stays where it is but changes colour, and moves between the two players' lists.
  on(
    'unit:transferred',
    (unit: Unit, player: Player, previousPlayer: Player) => {
      ctx.patches.tile(unit.tile());

      if (![player, previousPlayer].some((player) => ctx.view.owns(player))) {
        return;
      }

      ctx.patches.wholePlayer(
        filterToReference(PlayerWorld, PlayerTile, Tile, City)
      );
    }
  );

  // A rival's cities, as the map draws them, where something other than their size or disorder can change how they're
  //  drawn: their style (Civ2's eras, M2c) after an advance, their walls (#688) after a building or a Wonder (Civ2's
  //  Great Wall is walls in every one of its owner's cities, #1069). Each the player has been sent goes again, with its
  //  square, where its stand-in's style or walls change. None under rules that say neither.
  const drawnBy = (): boolean =>
      workerRules().cityStyle !== undefined ||
      workerRules().walled !== undefined,
    drawnAs = (unknownCity: UnknownCity): string =>
      JSON.stringify([unknownCity.style(), unknownCity.walled()]);

  const redrawRivalCities = (cities: City[]): void => {
    if (!drawnBy()) {
      return;
    }

    cities.forEach((city: City) => {
      if (ctx.view.owns(city.player())) {
        return;
      }

      const unknownCity = knownUnknownCity(city),
        playerTile = ctx.view.tile(city.tile());

      if (!unknownCity || !playerTile) {
        return;
      }

      const before = drawnAs(unknownCity);

      unknownCity.update(city);

      if (drawnAs(unknownCity) === before) {
        return;
      }

      ctx.patches.update(unknownCity.id(), () =>
        unknownCity.toPlainObject(
          ctx.dataFilter(filterToReference(Tile, Unit, Player))
        )
      );
      ctx.patches.tile(playerTile);
    });
  };

  // The same, read when the patch is built rather than now: a city's capture raises `city:captured` before the rules
  //  that take its buildings and Wonders with it have run (each a `Captured` rule of its own). A stand-in that is drawn
  //  as it was goes nowhere; one that changed is drawn again by the page from its city (`GameState`'s `drawnCity`).
  const redrawRivalCitiesLater = (cities: City[]): void => {
    if (!drawnBy()) {
      return;
    }

    cities.forEach((city: City) => {
      const unknownCity = knownUnknownCity(city);

      if (
        ctx.view.owns(city.player()) ||
        !unknownCity ||
        !ctx.view.tile(city.tile())
      ) {
        return;
      }

      ctx.patches.update(unknownCity.id(), () => {
        const before = drawnAs(unknownCity);

        unknownCity.update(city);

        return drawnAs(unknownCity) === before
          ? undefined
          : unknownCity.toPlainObject(
              ctx.dataFilter(filterToReference(Tile, Unit, Player))
            );
      });
    });
  };

  // A Wonder can be walls in all its owner's cities (Civ2's Great Wall, #1069), so a city changing hands or lost
  //  changes both players' others: a capture, a city lost, a civil war. Ours go in full on those already (#515).
  const citiesOf = (...players: (Player | null)[]): City[] =>
    players
      .filter(
        (player, index): player is Player =>
          player !== null && players.indexOf(player) === index
      )
      .flatMap((player: Player) => ctx.cities.getByPlayer(player));

  on('city:captured', (city: City, capturingPlayer: Player, player: Player) =>
    redrawRivalCitiesLater(citiesOf(capturingPlayer, player))
  );
  on('city:destroyed', (city: City) =>
    redrawRivalCitiesLater(citiesOf(city.player()))
  );
  on('player:civil-war', (loser: Player, rebels: Player) =>
    redrawRivalCitiesLater(citiesOf(loser, rebels))
  );
  // A building lost, sabotaged by a Diplomat or Spy (City Walls among the targets) or sold for want of gold to keep it:
  //  that city alone, a rival's or ours, which a rival's Diplomat can sabotage in its own turn.
  ['city:sabotaged', 'city:unsupported-improvement'].forEach((event) =>
    on(event, (city: City) => {
      if (ctx.view.owns(city.player())) {
        ctx.patches.city(city);

        return;
      }

      redrawRivalCitiesLater([city]);
    })
  );

  // Our build is told of in `Client/notifications/city.ts`, as a rival's wonder is. A rival's building can be its
  //  walls (#688). Our city goes in the hand-over's patch, which sends our cities in full.
  on('city:building-complete', (cityBuild) => {
    if (!ctx.view.owns(cityBuild.city().player())) {
      redrawRivalCities([cityBuild.city()]);

      return;
    }

    ctx.patches.update(cityBuild.id(), () =>
      cityBuild.toPlainObject(
        ctx.dataFilter(filterToReference(Tile, Unit, Player))
      )
    );
  });

  // A build dropped (#978), however it was: an advance gained in the middle of our turn (a goody hut, a Diplomat's
  //  theft, a city captured) or a rival's Wonder can leave the city screen and lists showing it until the hand-over,
  //  with nothing else sending it. So the build goes again (only ours, as a choice of ours does). A city on Auto has
  //  chosen again by the time the patch is built, which sends that. Not during our automated turn, whose end sends the
  //  whole player.
  on('city:building-cancelled', (cityBuild: CityBuild) => {
    if (!ctx.automation.automatedTurn()) {
      ctx.patches.cityBuild(cityBuild);
    }
  });

  // A Wonder can be walls in all its owner's cities, from when it's built until it's obsolete (Civ2's Great Wall,
  //  #1069). Ours go in full, now rather than at the hand-over: anyone's advance can make a Wonder obsolete mid-turn
  //  (a hut, a theft, a parley).
  ['wonder:built', 'wonder:obsolete'].forEach((event) =>
    on(event, (_wonder: unknown, city: City) => {
      if (workerRules().walled !== undefined && ctx.view.owns(city.player())) {
        ctx.patches.cities();
      }

      redrawRivalCities(ctx.cities.getByPlayer(city.player()));
    })
  );

  // The advance is told of in `Client/notifications/player.ts`.
  on('player:research-complete', (playerResearch) => {
    if (!ctx.view.owns(playerResearch.player())) {
      redrawRivalCities(ctx.cities.getByPlayer(playerResearch.player()));

      return;
    }

    ctx.patches.update(playerResearch.id(), () =>
      playerResearch.toPlainObject(ctx.dataFilter(filterToReference(Player)))
    );
  });

  // The cities whose improvements are gone (#184). The player is told in `Client/notifications/city.ts`.
  on(
    'city-improvement:obsolete',
    (
      player: Player,
      _advance: Advance,
      _ImprovementType: typeof CityImprovement,
      cityImprovements: CityImprovement[]
    ) => {
      if (!ctx.view.owns(player)) {
        return;
      }

      cityImprovements.forEach((cityImprovement) =>
        ctx.patches.city(cityImprovement.city())
      );
    }
  );

  // The hut is gone from the square, whoever found it (#138). The finder is told in `Client/notifications/unit.ts`.
  on('goody-hut:action-performed', (goodyHut: GoodyHut) =>
    ctx.patches.tile(goodyHut.tile())
  );

  return () =>
    listeners.forEach(([event, listener]) => engine.off(event, listener));
};

export default registerPatchEvents;
