import Player from '@civ-clone/core-player/Player';
import PlayerResearch from '@civ-clone/core-science/PlayerResearch';

export type Joining = {
  /** A player `Added` effect: `player` is joining, and its advances announce no age until the next turn starts. */
  joined: (player: Player) => void;
  /** A turn `Start` effect: every player that joined has settled in. */
  settled: () => void;
  /** A `ready` for `reachAge`: whether `playerResearch`'s player has settled in. */
  ready: (playerResearch: PlayerResearch) => boolean;
};

/**
 * Keeps quiet about the ages of players who are joining the game: those added while it is set up, and any added part-way
 * through a turn (a civilization that comes back with the advances it inherits, say), until the next turn starts. The
 * advances a civilization starts with are given as it is added, so they reach no age. Nothing is saved: a loaded game's
 * players are settled in.
 */
export const joining = (): Joining => {
  const players = new Set<Player>();

  return {
    joined: (player: Player): void => {
      players.add(player);
    },
    settled: (): void => players.clear(),
    ready: (playerResearch: PlayerResearch): boolean =>
      !players.has(playerResearch.player()),
  };
};

export default joining;
