import Advance from '@civ-clone/core-science/Advance';
import Age from '../Age';

/**
 * An `AgeOf` effect for a ruleset where each advance belongs to one age: the latest of `ages` (in order) that any known
 * advance belongs to, by `ageFor`, or the first when none does, so a civilization that knows nothing is in the first
 * age. An advance `ageFor` doesn't place (one that can be repeated, say) counts for nothing.
 */
export const latestAge = (
  ages: readonly (typeof Age)[],
  ageFor: (AdvanceType: typeof Advance) => typeof Age | undefined
): ((known: (typeof Advance)[]) => typeof Age) => {
  if (ages.length === 0) {
    throw new RangeError('There must be at least one age.');
  }

  return (known: (typeof Advance)[]): typeof Age =>
    known.reduce((latest: typeof Age, AdvanceType: typeof Advance) => {
      const age = ageFor(AdvanceType);

      return age !== undefined && ages.indexOf(age) > ages.indexOf(latest)
        ? age
        : latest;
    }, ages[0]);
};

export default latestAge;
