import {
  RuleRegistry,
  instance as ruleRegistryInstance,
} from '@civ-clone/core-rule/RuleRegistry';
import { ageOf, knownAdvances } from './ageOf';
import Advance from '@civ-clone/core-science/Advance';
import AgeReached from '../Rules/AgeReached';
import PlayerResearch from '@civ-clone/core-science/PlayerResearch';

/**
 * A research `Complete` effect: when the advance just gained takes its player into a new age, processes `AgeReached`
 * with the age and the one before it. Every way of gaining an advance (research, a hut, a Diplomat, a treaty) runs
 * `Complete`, so this hears them all. An advance that jumps a player over an age reaches the later one, once. Each
 * advance is judged by what was known up to it, so one gained while another is told of (a bonus advance from a
 * `Complete` rule) reaches its own age, told of first, and the first advance still reaches its own.
 *
 * `ready` says whether to look at all: a ruleset passes one that is false while a game is being set up, so the
 * advances a civilization starts with don't announce an age (`lib/joining`). A game that is loaded runs no `Complete`,
 * so nothing is announced then either.
 */
export const reachAge =
  (
    ruleRegistry: RuleRegistry = ruleRegistryInstance,
    ready: (playerResearch: PlayerResearch) => boolean = () => true
  ): ((playerResearch: PlayerResearch, advance: Advance) => void) =>
  (playerResearch: PlayerResearch, advance: Advance): void => {
    if (!ready(playerResearch)) {
      return;
    }

    // As they were up to and including this advance: a rule that gains the player another as this one is told of
    //  (a bonus advance) has the later one told of on its own.
    const index = playerResearch.complete().lastIndexOf(advance);

    if (index === -1) {
      return;
    }

    const known = knownAdvances(playerResearch),
      previous = ageOf(known.slice(0, index), ruleRegistry),
      age = ageOf(known.slice(0, index + 1), ruleRegistry);

    if (age === null || previous === null || age === previous) {
      return;
    }

    ruleRegistry.process(AgeReached, playerResearch, age, previous);
  };

export default reachAge;
