import And from './Criteria/And';
import Criteria from './Criteria';
import Criterion from './Criterion';
import Description, { EffectDescription } from './Description';
import Effect from './Effect';
import { Normal } from './Priorities';
import Priority from './Priority';

export interface IRule<C extends any[] = any[], R = any> {
  disable(): void;
  enable(): void;
  enabled(): boolean;
  id(): string | null;
  priority(): Priority;
  process(...args: C): R | void;
  validate(...args: C): boolean;
}

// How many times any rule has been switched on or off. `RuleRegistry` keeps its answer to "which rules of this type are
//  enabled" and needs to know when to look again; a rule is switched through the rule itself as often as through a
//  registry, so the rule is the only place that can count.
let switches = 0;

export const switchCount = (): number => switches;

export class Rule<C extends any[] = any[], R = any> implements IRule<C, R> {
  private _criteria: Criteria<C> | undefined;
  // Only a rule that describes itself has the field: a rule is reachable from saved state (a unit's `_busy`), and
  //  an empty list on every one would change what is saved.
  private _descriptions?: EffectDescription[];
  private _enabled: boolean = true;
  private _effect: Effect<C, R> | undefined;
  private _id: string | null = null;
  private _priority: Priority = new Normal();

  /**
   * An optional identifier, as the first argument:
   *
   * ```ts
   * new Created(
   *   'civ1-city:city/created/register',
   *   new Criterion(…),
   *   new Effect(…)
   * )
   * ```
   *
   * **Optional, so this lands package by package.** Unnamed rules keep working
   * exactly as before — of the 1,055 rules a real game registers, most are
   * collecting rules that compose fine and have no reason to be addressable.
   * What an identifier buys is the ability to name *one instance*, which is
   * what `RuleRegistry.replace`, `disable`, `before` and `after` need and what
   * no amount of subclassing can provide: there are 1,055 instances and 163
   * classes.
   *
   * The convention is `package:path/to/rule`, so an identifier says where to
   * look for what it names.
   */
  constructor(
    ...values: (string | Priority | Criterion<C> | Effect<C, R> | Description)[]
  ) {
    const criteria: Criterion<C>[] = [];

    values.forEach(
      (
        value: string | Priority | Criterion<C> | Effect<C, R> | Description
      ): void => {
        if (typeof value === 'string') {
          if (this._id !== null) {
            throw new TypeError(
              `Rule: id already specified as '${this._id}', but '${value}' ` +
                'was also provided.'
            );
          }

          this._id = value;

          return;
        }

        if (value instanceof Effect) {
          if (this._effect) {
            throw new TypeError(
              'Rule: effect already specified, but another was provided.'
            );
          }

          this._effect = value;

          return;
        }

        if (value instanceof Criterion) {
          criteria.push(value);

          return;
        }

        // What it does, as data, for whatever explains the rules (civ-clone/web-renderer#1196). Known by its shape as
        //  well, so one from another copy of this package is read too, rather than taken for the priority.
        if (
          value instanceof Description ||
          typeof (value as unknown as Description)?.effects === 'function'
        ) {
          (this._descriptions ??= []).push(
            ...(value as unknown as Description).effects()
          );

          return;
        }

        // Anything with a `value()` is taken for a priority, as one from another copy of this package would be.
        if (
          value instanceof Priority ||
          typeof (value as unknown as Priority)?.value === 'function'
        ) {
          this._priority = value as unknown as Priority;

          return;
        }

        throw new TypeError(
          `Rule: '${
            (value as object)?.constructor?.name ?? typeof value
          }' is not an id, Priority, Criterion, Effect or Description ` +
            '(is it from another copy of @civ-clone/core-rule?).'
        );
      }
    );

    if (criteria.length) {
      this._criteria = new And(...criteria);
    }
  }

  /**
   * What the rule does, as data (`Description`): every effect described, in the order given, or none for a rule that
   *  says nothing about itself. Read whether or not the rule is enabled: whatever explains the rules asks `enabled()`.
   */
  descriptions(): EffectDescription[] {
    return [...(this._descriptions ?? [])];
  }

  disable(): void {
    if (this._enabled) {
      switches++;
    }

    this._enabled = false;
  }

  enable(): void {
    if (!this._enabled) {
      switches++;
    }

    this._enabled = true;
  }

  /** The identifier this rule was constructed with, if any. */
  id(): string | null {
    return this._id;
  }

  enabled(): boolean {
    return this._enabled;
  }

  priority(): Priority {
    return this._priority;
  }

  process(...args: C): R | void {
    if (!this._enabled) {
      return;
    }

    if (this._effect instanceof Effect) {
      return this._effect.apply(...args);
    }
  }

  validate(...args: C): boolean {
    if (!this._enabled) {
      return false;
    }

    if (this._criteria instanceof Criterion) {
      return this._criteria.validate(...args);
    }

    return true;
  }
}

export default Rule;
