import {
  LAND_UPRISING_RULE as CIV1_LAND_UPRISING_RULE,
  RAIDERS_ONLY_RULE as CIV1_RAIDERS_ONLY_RULE,
  RANSOM_RULE as CIV1_RANSOM_RULE,
} from '@civ-clone/civ1-barbarians/RuleIds';
import { Game, defaultGame } from '@civ-clone/core-game';
import { KEEP_BUILD_RULE as CIV1_KEEP_BUILD_RULE } from '@civ-clone/civ1-city/RuleIds';
import RuleSet from '@civ-clone/core-rule/RuleSet';
import cityBuild from './Rules/City/build';
import cityCaptured from './Rules/City/captured';
import cityGainedImprovements from './Rules/City/gainedImprovements';
import cityLostImprovements from './Rules/City/lostImprovements';
import cityProcessYield from './Rules/City/processYield';
import { describedRequirements } from './Requirements';
import playerResearchComplete from './Rules/Player/researchComplete';
import turnStart from './Rules/Turn/start';
import unitDestroyed from './Rules/Unit/destroyed';
// civ-clone/web-renderer#960
import {
  DEFECTORS_STAY_VETERAN,
  EVEN_ADVANCE_STEALING,
  SDI_DEFENSE_SPARES_CITIES,
  UNITED_NATIONS_STOPS_COMPUTER_WARS,
} from './RuleSets';
import {
  HALVE_CITIES_RULE,
  KEEP_VETERAN_RULE,
  STEAL_RULE,
  UNITED_NATIONS_PACIFIED_RULE,
} from './RuleIds';
import {
  CHIEFTAIN_SETTLERS_RULE as CIV1_CHIEFTAIN_SETTLERS_RULE,
  HALVE_CITIES_RULE as CIV1_HALVE_CITIES_RULE,
  START_AFRESH_RULE as CIV1_START_AFRESH_RULE,
  STEAL_RULE as CIV1_STEAL_RULE,
} from '@civ-clone/civ1-unit/RuleIds';
import { UNITED_NATIONS_PACIFIED_RULE as CIV1_UNITED_NATIONS_PACIFIED_RULE } from '@civ-clone/civ1-wonder/RuleIds';
import playerPacified from './Rules/Player/pacified';
import unitDetonated from './Rules/Unit/detonated';
import unitTechnologyStolen from './Rules/Unit/technologyStolen';
import unitTransferred from './Rules/Unit/transferred';
// civ-clone/web-renderer#959
import { SETTLERS_WAIT_FOR_SIZE_TWO } from './RuleSets';
import { SETTLERS_WAIT_RULE } from './RuleIds';
import cityHold from './Rules/City/hold';
// civ-clone/web-renderer#1072
import { COST_RULE as CIV1_COST_RULE } from '@civ-clone/civ1-science/RuleIds';
import { FIXED_RESEARCH_COSTS } from './RuleSets';
import { TIERED_COST_RULE } from './RuleIds';
import researchCost from './Rules/Research/cost';
// civ-clone/web-renderer#1076
import {
  AGE_BY_TIER_RULE,
  AGE_REACHED_RULE,
  AGES_JOINED_RULE,
  AGES_SETTLED_RULE,
  REACH_AGE_RULE,
} from './RuleIds';
import { AGES } from './RuleSets';
import researchAge from './Rules/Research/age';
// civ-clone/web-renderer#1077
import {
  CATCH_UP_FROM_RENAISSANCE_RULE,
  RATE_MULTIPLIER_BY_AGE_RULE,
} from './RuleIds';
import {
  CATCH_UP_RULE as CIV1_CATCH_UP_RULE,
  RATE_MULTIPLIER_RULE as CIV1_RATE_MULTIPLIER_RULE,
} from '@civ-clone/civ1-science/RuleIds';
import { RESEARCH_COST_BY_AGE } from './RuleSets';
import rateByAge from './Rules/Research/rateByAge';
// civ-clone/web-renderer#973
import { ADVANCE_COUNT_RULE as CIV1_ADVANCE_COUNT_RULE } from '@civ-clone/civ1-science/RuleIds';
import { EVERY_ADVANCE_COUNT_RULE } from './RuleIds';
import { STARTING_ADVANCES_COUNT } from './RuleSets';
import advanceCount from './Rules/Research/advanceCount';
// civ-clone/web-renderer#1008
import { BARBARIAN_ACTIVITY, BARBARIAN_ACTIVITY_LEVEL } from './RuleSets';
import { DEFAULT_MEMBER, MEMBERS } from './BarbarianActivities';
import { BARBARIAN_ACTIVITY_RULE } from './RuleIds';
import barbarianActivity from './Rules/Barbarians/activity';
// civ-clone/web-renderer#1029
import {
  NO_RAILROAD_IN_CITIES_RULE as CIV1_NO_RAILROAD_IN_CITIES_RULE,
  RAILROAD_MOVEMENT_RULE as CIV1_RAILROAD_MOVEMENT_RULE,
} from '@civ-clone/civ1-unit/RuleIds';
import {
  RAILROAD_IN_CITIES_RULE,
  RAILROAD_ON_BOTH_SQUARES_RULE,
} from './RuleIds';
import { RAILROADS_IN_CITIES } from './RuleSets';
import railroadsInCities from './Rules/Unit/railroadsInCities';

export const register = (game: Game): void => {
  // The ids superseded are imported from their packages, so renaming one breaks this build rather than leaving both
  //  rules running. The sets before their rules, so each rule is switched as it arrives: the Hydro Plant's starts off.
  //  A set of its own for each game, as a game may add to its sets.
  game.ruleSets.register(
    new RuleSet(
      ENHANCED,
      new RuleSet(
        HYDRO_PLANT_SITE,
        {
          enabled: false,
          supersedes: [CIV1_HYDRO_PLANT_SITE_RULE],
        },
        HYDRO_PLANT_SITE_RULE
      ),
      new RuleSet(
        BARBARIAN_LEADER_RANSOM,
        { supersedes: [CIV1_RANSOM_RULE] },
        RANSOM_RULE
      ),
      // Rules added to Civ1's, so nothing to supersede: switched off, v474.05's play is what is left.
      new RuleSet(OBSOLETE_BUILDS, ...OBSOLETE_BUILDS_RULES),
      // Only the human's capture: v474.05 already has a computer player choose again, as `civ1-city`'s rule does.
      new RuleSet(
        CAPTURED_CITY_BUILD,
        { supersedes: [CIV1_KEEP_BUILD_RULE] },
        CLEAR_CAPTURED_BUILD_RULE
      ),
      new RuleSet(
        POLLUTION_IN_EVERY_CITY,
        { supersedes: [CIV1_POLLUTION_RULE] },
        POLLUTION_RULE
      ),
      new RuleSet(
        BARBARIAN_CITY_BUILDS,
        { supersedes: [CIV1_RAIDERS_ONLY_RULE] },
        RAIDERS_ONLY_RULE
      ),
      new RuleSet(
        BARBARIAN_UPRISINGS,
        { supersedes: [CIV1_LAND_UPRISING_RULE] },
        LAND_UPRISING_RULE
      ),
      // civ-clone/web-renderer#960: two as play was, and two new, off to start with.
      new RuleSet(
        UNITED_NATIONS_STOPS_COMPUTER_WARS,
        { supersedes: [CIV1_UNITED_NATIONS_PACIFIED_RULE] },
        UNITED_NATIONS_PACIFIED_RULE
      ),
      new RuleSet(
        EVEN_ADVANCE_STEALING,
        { supersedes: [CIV1_STEAL_RULE] },
        STEAL_RULE
      ),
      new RuleSet(
        SDI_DEFENSE_SPARES_CITIES,
        { enabled: false, supersedes: [CIV1_HALVE_CITIES_RULE] },
        HALVE_CITIES_RULE
      ),
      new RuleSet(
        DEFECTORS_STAY_VETERAN,
        { enabled: false, supersedes: [CIV1_START_AFRESH_RULE] },
        KEEP_VETERAN_RULE
      ),
      // civ-clone/web-renderer#959. On Chieftain, v474.05's rule holds the same build in a smaller set of cities:
      //  superseded, so a held build gives one reason, this one. With it on, `civ1-unit`'s rule that removes a size-1
      //  city for its Settlers is never reached, so it needn't be superseded too.
      new RuleSet(
        SETTLERS_WAIT_FOR_SIZE_TWO,
        { supersedes: [CIV1_CHIEFTAIN_SETTLERS_RULE] },
        SETTLERS_WAIT_RULE
      ),
      // civ-clone/web-renderer#1072
      new RuleSet(
        FIXED_RESEARCH_COSTS,
        { enabled: false, supersedes: [CIV1_COST_RULE] },
        TIERED_COST_RULE
      ),
      // civ-clone/web-renderer#1076: rules added to Civ1's, so nothing to supersede.
      new RuleSet(
        AGES,
        { enabled: false },
        AGE_BY_TIER_RULE,
        AGES_JOINED_RULE,
        AGES_SETTLED_RULE,
        REACH_AGE_RULE,
        AGE_REACHED_RULE
      ),
      // civ-clone/web-renderer#1077
      new RuleSet(
        RESEARCH_COST_BY_AGE,
        {
          enabled: false,
          supersedes: [CIV1_RATE_MULTIPLIER_RULE, CIV1_CATCH_UP_RULE],
        },
        RATE_MULTIPLIER_BY_AGE_RULE,
        CATCH_UP_FROM_RENAISSANCE_RULE
      ),
      // civ-clone/web-renderer#973: today's count, so on to start with.
      new RuleSet(
        STARTING_ADVANCES_COUNT,
        { supersedes: [CIV1_ADVANCE_COUNT_RULE] },
        EVERY_ADVANCE_COUNT_RULE
      ),
      // civ-clone/web-renderer#1008: a choice can't start off, and a set switched off doesn't reach into one, so the set
      //  holds the one rule that answers with the level, and the choice beneath it only says which.
      new RuleSet(
        BARBARIAN_ACTIVITY,
        { enabled: false },
        BARBARIAN_ACTIVITY_RULE,
        new RuleSet(
          BARBARIAN_ACTIVITY_LEVEL,
          { exclusive: true, default: DEFAULT_MEMBER },
          ...MEMBERS
        )
      ),
      // civ-clone/web-renderer#1029: today's railroads, so on to start with.
      new RuleSet(
        RAILROADS_IN_CITIES,
        {
          supersedes: [
            CIV1_NO_RAILROAD_IN_CITIES_RULE,
            CIV1_RAILROAD_MOVEMENT_RULE,
          ],
        },
        RAILROAD_IN_CITIES_RULE,
        RAILROAD_ON_BOTH_SQUARES_RULE
      )
    )
  );

  game.rules.register(
    ...cityBuild(game),
    ...cityCaptured(game),
    ...cityProcessYield(game),
    ...playerResearchComplete(game),
    ...turnStart(game),
    ...unitDestroyed(game),
    // civ-clone/web-renderer#960
    ...playerPacified(game),
    ...unitTechnologyStolen(game),
    ...unitDetonated(game),
    ...unitTransferred(game),
    // civ-clone/web-renderer#959
    ...cityHold(game),
    // What a city can no longer build for other reasons than a discovery: as it happens (civ-clone/web-renderer#965).
    ...cityLostImprovements(game),
    ...cityGainedImprovements(game),
    // civ-clone/web-renderer#1072
    ...researchCost(game),
    // civ-clone/web-renderer#1076
    ...researchAge(game),
    // civ-clone/web-renderer#1077
    ...rateByAge(game),
    // civ-clone/web-renderer#973
    ...advanceCount(),
    // civ-clone/web-renderer#1008
    ...barbarianActivity(game),
    // civ-clone/web-renderer#1029
    ...railroadsInCities(game)
  );

  // The entry for the Hydro Plant's site rule, which is written by hand: in force while the rule is on, as the
  //  civilopedia and the reasons a city can't build something follow the rule with the entry's id.
  game.requirements.add(null, ...describedRequirements);
};

// The plugin loader imports each package for this side effect, as it does `registerRules` elsewhere.
register(defaultGame);

export default register;
