import Age from '../Age';
import Engine from '@civ-clone/core-engine/Engine';
import PlayerResearch from '@civ-clone/core-science/PlayerResearch';

/** An `AgeReached` effect: tells the engine's listeners (`player:age-reached`). */
export const emitAgeReached =
  (
    engine: Engine
  ): ((
    playerResearch: PlayerResearch,
    age: typeof Age,
    previous: typeof Age
  ) => void) =>
  (
    playerResearch: PlayerResearch,
    age: typeof Age,
    previous: typeof Age
  ): void => {
    engine.emit('player:age-reached', playerResearch, age, previous);
  };

export default emitAgeReached;
