import {
  RuleRegistry,
  instance as ruleRegistryInstance,
} from '@civ-clone/core-rule/RuleRegistry';
import Advance from '@civ-clone/core-science/Advance';
import Age from '../Age';
import AgeOf from '../Rules/AgeOf';
import PlayerResearch from '@civ-clone/core-science/PlayerResearch';

/** The age a civilization that knows `known` is in, or `null` when no `AgeOf` rule answers (ages aren't in play). */
export const ageOf = (
  known: (typeof Advance)[],
  ruleRegistry: RuleRegistry = ruleRegistryInstance
): typeof Age | null => {
  const [age] = ruleRegistry.process(AgeOf, known);

  return age ?? null;
};

/** The advances a player knows, as their types. */
export const knownAdvances = (
  playerResearch: PlayerResearch
): (typeof Advance)[] =>
  playerResearch
    .complete()
    .map((advance: Advance) => advance.sourceClass<typeof Advance>());

/**
 * The age a player is in: worked out from what they know, so nothing is saved for it and a game loads in the age it
 * was saved in.
 */
export const playerAge = (
  playerResearch: PlayerResearch,
  ruleRegistry: RuleRegistry = ruleRegistryInstance
): typeof Age | null => ageOf(knownAdvances(playerResearch), ruleRegistry);

export default ageOf;
